def _check_image_height_and_width(image_data, image_height, image_width):
    actual_width, actual_height = utils.get_pil_img_dim(image_data)
    if image_height is not None and actual_height != image_height:
        logger.error(
            "image_height does not match with image_data or image_path, "
            "so getting image_height from actual image."
        )
        image_height = actual_height
    if image_width is not None and actual_width != image_width:
        logger.error(
            "image_width does not match with image_data or image_path, "
            "so getting image_width from actual image."
        )
        image_width = actual_width
    return image_height, image_width

LabelFile.load.source:
def load(self, filename):
    try:
        with utils.io_open(filename, "r") as f:
            data = json.load(f)

        if data.get("version") is None:
            logger.warning(
                f"Loading JSON file ({filename}) of unknown version"
            )

        if data["shapes"]:
            for i in range(len(data["shapes"])):
                shape_points = data["shapes"][i]["points"]
                if (
                    data["shapes"][i]["shape_type"] == "rectangle"
                    and len(shape_points) == 2
                ):
                    logger.warning(
                        "UserWarning: Diagonal vertex mode is deprecated in X-AnyLabeling release v2.2.0 or later.\n"
                        "Please update your code to accommodate the new four-point mode."
                    )
                    data["shapes"][i]["points"] = (
                        utils.rectangle_from_diagonal(shape_points)
                    )

        image_path = self._image_path_override
        if image_path is None:
            if self.image_dir:
                image_path = osp.join(
                    self.image_dir, osp.basename(data["imagePath"])
                )
            else:
                image_path = osp.join(
                    osp.dirname(filename), data["imagePath"]
                )
                if not osp.isfile(image_path):
                    local_image_path = osp.join(
                        osp.dirname(filename),
                        osp.basename(data["imagePath"]),
                    )
                    if osp.isfile(local_image_path):
                        image_path = local_image_path
        if data["imageData"] is not None:
            image_data = base64.b64decode(data["imageData"])
        else:
            # relative path from label file to relative path from cwd
            image_data = self.load_image_file(image_path)
            if image_data is None:
                raise LabelFileError(
                    QCoreApplication.translate(
                        "LabelFile", "Failed opening image file: %s"
                    )
                    % image_path
                )

        flags = data.get("flags", {})

        utils.get_pil_img_dim(image_data)

        identity_result = normalize_shape_identities(
            (
                shape.get(SHAPE_ID_FIELD, MISSING_SHAPE_ID)
                for shape in data["shapes"]
            )
        )
        shapes = []
        for raw_shape, shape_id in zip(
            data["shapes"], identity_result.identities
        ):
            normalized_shape = dict(raw_shape)
            normalized_shape[SHAPE_ID_FIELD] = shape_id
            shapes.append(Shape().load_from_dict(normalized_shape))
        if identity_result.diagnostics:
            logger.warning(
                "Repaired %d Shape identities while loading %s: %s",
                identity_result.repaired_count,
                filename,
                describe_shape_identity_diagnostics(
                    identity_result.diagnostics
                ),
            )

    except Exception as e:  # noqa
        raise LabelFileError(e) from e

    other_data = {}
    for key, value in data.items():
        if key not in XLABEL_BASIC_FIELDS:
            other_data[key] = value

    if IMAGE_TAGS_FIELD in data:
        other_data[IMAGE_TAGS_FIELD] = utils.normalize_image_tags(
            data[IMAGE_TAGS_FIELD], filename
        )

    # Add new fields if not available
    other_data["description"] = other_data.get("description", "")
    checked = data.get("checked", False)
    other_data["checked"] = (
        "failed" if checked == "failed" else checked is True
    )

    # Only replace data after everything is loaded.
    self.flags = flags
    self.shapes = shapes
    self.image_path = data["imagePath"]
    self.resolved_image_path = image_path
    self.image_data = image_data
    self.filename = filename
    self.other_data = other_data

Canvas.store_shapes.source:
def store_shapes(self):
    """Store shapes for restoring later (Undo feature)"""
    shapes_backup = []
    for shape in self.shapes:
        shapes_backup.append(shape.copy())
    if len(self.shapes_backups) > self.num_backups:
        self.shapes_backups = self.shapes_backups[-self.num_backups - 1 :]
    self.shapes_backups.append(shapes_backup)

Shape.make_path.source:
def make_path(self):
    """Create a path from shape"""
    if not self.points:
        return QtGui.QPainterPath()
    if self.shape_type == "rectangle":
        path = QtGui.QPainterPath()
        path.addPolygon(QtGui.QPolygonF(self.points))
    elif self.shape_type == "cuboid":
        path = QtGui.QPainterPath(self.points[0])
        if len(self.points) >= 4:
            for p in self.points[1:4]:
                path.lineTo(p)
            path.closeSubpath()
        if len(self.points) >= 8:
            back_path = QtGui.QPainterPath(self.points[4])
            for p in self.points[5:8]:
                back_path.lineTo(p)
            back_path.closeSubpath()
            path.addPath(back_path)
    elif self.shape_type == "circle":
        path = QtGui.QPainterPath()
        if len(self.points) == 2:
            rectangle = self.get_circle_rect_from_line(self.points)
            path.addEllipse(rectangle)
    else:
        path = QtGui.QPainterPath()
        path.addPolygon(QtGui.QPolygonF(self.points))
    return path

Shape.bounding_rect.source:
def bounding_rect(self):
    """Return bounding rectangle of the shape"""
    return self.make_path().boundingRect()
